		part(V(0,-.15,0),V(1.45,1.45,1.45),4,nil,Enum.PartType.Ball)
		bar(0,.75,0,.45,.6,.45,5);bar(0,1.05,0,.52,.25,.52,1)
	elseif shapeName=="VaultChest" then
		bar(0,-.2,0,2.5,1.3,1.5,2);bar(0,.6,0,2.6,.4,1.6,3)
		bar(0,.1,-.8,.4,.5,.12,5)
		for _,x in ipairs({-.8,.8}) do bar(x,0,0,.2,1.75,1.62,6) end
	elseif shapeName=="TimberBundle" then
		for _,c in ipairs({{-.45,-.25},{.4,-.3},{0,.3}}) do part(V(c[1],0,c[2]),V(.7,2.5,.7),1,CFrame.Angles(0,math.pi/4,0)) end
		for _,y in ipairs({-.65,.65}) do bar(0,y,-.1,1.75,.18,1.4,3) end
	elseif shapeName=="Surveyor" then
		bar(0,-1.25,0,2.4,.5,2.4,6);bar(0,-.3,0,.6,1.5,.6,1)
		bar(0,.55,0,2.6,.3,1.8,3);part(V(0,1.15,0),V(.42,.42,2.2),2,CFrame.Angles(.35,0,0))
		part(V(0,1.75,.2),V(.55,.55,.55),5,CFrame.Angles(0,math.pi/4,math.pi/4))
	elseif shapeName=="Shellwarden" then
		part(V(0,1.8,-.2),V(5.6,3.2,5.6),9,CFrame.Angles(0,math.pi/4,0))
		part(V(0,3.75,-.2),V(3,1.4,3),10,CFrame.Angles(0,math.pi/4,0))
		bar(0,1,-3.9,1.8,1.4,1.6,6);bar(0,1.3,-4.6,1.2,.25,.2,5)
		for _,c in ipairs({{2.6,1.8},{-2.6,1.8},{2.6,-1.8},{-2.6,-1.8}}) do part(V(c[1],-.35,c[2]),V(1,1.2,1),1) end
	elseif shapeName=="Tidewing" then
		part(V(0,.7,0),V(3.6,1.6,9),3)
		for _,side in ipairs({-1,1}) do
			part(V(side*5,.5,.3),V(7.6,.35,5.6),4,CFrame.Angles(0,0,side*.12))
			part(V(side*1.2,.4,6.3),V(.6,.4,1.8),2)
		end
		part(V(0,.4,-5.4),V(.5,.5,3.6),1);part(V(0,1.6,1.6),V(1.2,.4,1.2),5)
	else
		bar(0,-.8,0,2.5,.6,2.2,9)
		part(V(0,.7,0),V(.9,2.5,.9),5,CFrame.Angles(0,math.pi/4,.1))
		part(V(-.9,-.1,.2),V(.6,1.5,.6),4,CFrame.Angles(0,math.pi/4,.25))
		part(V(.8,0,-.3),V(.6,1.7,.6),10,CFrame.Angles(0,math.pi/4,-.2))
	end
	model.WorldPivot=CFrame.new()
	model:SetAttribute("BoundedProxy",true)
	return model
end
-- END BOUNDED PROXIES

-- Bounded part fallback for the tinted ore cluster (never triangle-per-part).
local function clusterProxy(shapeName,scale,tint)
	if shapeName~="OreCluster" then return nil end
	local model=Instance.new("Model")
	for _,spec in ipairs({{0,.75,0,.55,1.6,0,0},{.42,.5,.15,.42,1.1,.15,-.5},{-.4,.55,.2,.45,1.2,.2,.55}}) do
		local p=Instance.new("Part")
		p.Name="Authored proxy"
		p.Anchored,p.CanCollide,p.CanTouch,p.CanQuery=true,false,false,false
		p.CastShadow=false
		p.Material=Enum.Material.SmoothPlastic
		p.Color=tint or palette[TINT_INDEX]
		p.Size=Vector3.new(spec[4],spec[5],spec[4])*scale
		p.CFrame=CFrame.new(Vector3.new(spec[1],spec[2],spec[3])*scale)*CFrame.Angles(spec[6],math.pi/4,spec[7])
		p.Parent=model
	end
	model.WorldPivot=CFrame.new()
	model:SetAttribute("BoundedProxy",true)
	return model
end

-- Geometry fallback is selected globally after the first unavailable mesh allocation.
local prototypes={}
local prototypeCount=0
local editableAvailable=true
local function prototype(shapeName,scale,tint)
	local key=shapeName..":"..tostring(scale)..(if tint then ":"..tint:ToHex() else "")
	local function shade(index) return if tint and index==TINT_INDEX then tint else palette[index] end
	local cached=prototypes[key]
	if cached then
		while cached.building do task.wait() end
		return cached.visual,false
	end
	local shape=shapes[shapeName]
	if not shape then return nil,false end
	local retain=prototypeCount<48
	local entry={building=true}
	if retain then prototypes[key]=entry;prototypeCount+=1 end
	local vertices={}
	local low=Vector3.new(math.huge,math.huge,math.huge)
	local high=Vector3.new(-math.huge,-math.huge,-math.huge)
	for _,xyz in ipairs(shape.vertices) do
		local v=Vector3.new(table.unpack(xyz))*scale
		table.insert(vertices,v)
		low=Vector3.new(math.min(low.X,v.X),math.min(low.Y,v.Y),math.min(low.Z,v.Z))
		high=Vector3.new(math.max(high.X,v.X),math.max(high.Y,v.Y),math.max(high.Z,v.Z))
	end
	local mesh,visual
	if editableAvailable and retain then
		local ok,result=pcall(function()
			mesh=AssetService:CreateEditableMesh()
			assert(mesh,"Editable mesh unavailable")
			local ids,shades={},{}
			for _,v in ipairs(vertices) do table.insert(ids,mesh:AddVertex(v)) end
			for index in ipairs(palette) do table.insert(shades,mesh:AddColor(shade(index),1)) end
			for _,f in ipairs(shape.faces) do
				local face=mesh:AddTriangle(ids[f[1]],ids[f[2]],ids[f[3]])
				mesh:SetFaceColors(face,{shades[f[4]],shades[f[4]],shades[f[4]]})
			end
			local p=AssetService:CreateMeshPartAsync(Content.fromObject(mesh))
			p.DoubleSided=true
			p.Anchored,p.CanCollide,p.CanTouch,p.CanQuery=true,false,false,false
			p.Material=Enum.Material.SmoothPlastic
			-- MeshPart geometry is centered on its bounding box. Preserve the
			-- authored origin so native and wedge fallback silhouettes align.
			p.PivotOffset=CFrame.new(-(low+high)/2)
			return p
		end)
		if ok then visual=result else
			editableAvailable=false
			if mesh then mesh:Destroy();mesh=nil end
		end
	end
	if not visual then
		-- Bounded authored proxy or nothing: the anchor's own geometry stays as-is.
		visual=makeProxy(shapeName,scale) or clusterProxy(shapeName,scale,tint)
	end
	if visual then visual.Name=shapeName.." Sculpture" end
	entry.visual,entry.mesh,entry.building=visual,mesh,false
	return visual,not retain
end
-- Legacy AetherSculpture anchors (SculptureScale) render here; Shape parts sized by
-- the §10 contract are meshed by the MeshForge client script (forge.client.lua).
local CREATURES={Tidewing=true,Shellwarden=true}
local function build(anchor)
	local shapeName=anchor:GetAttribute("Shape")
	if not shapes[shapeName] then return end
	-- Contract-sized parts (ShapeScale, or no SculptureScale) belong to MeshForge.
	if not CREATURES[shapeName] and (anchor:GetAttribute("ShapeScale")~=nil or anchor:GetAttribute("SculptureScale")==nil) then return end
	local scale=anchor:GetAttribute("SculptureScale") or 1
	if type(scale)~="number" or scale<=0 or scale>100 or scale~=scale then return end
	local tint=anchor:GetAttribute("Tint")
	if typeof(tint)~="Color3" then tint=nil end
	local template,temporary=prototype(shapeName,scale,tint)
	if not template then return end
	local visual=if temporary then template else template:Clone()
	if not anchor.Parent then visual:Destroy();return end
	visual:PivotTo(anchor.CFrame)
	visual.Parent=anchor
	-- Gameplay anchors retain collision/prompts; replicated state only changes art.
	local surfaceColors={}
	local surfaces=visual:GetDescendants()
	if visual:IsA("BasePart") then table.insert(surfaces,visual) end
	for _,part in ipairs(surfaces) do if part:IsA("BasePart") then surfaceColors[part]=part.Color end end
	local function stateAppearance()
		local state=anchor:GetAttribute("VisualState")
		for part,color in pairs(surfaceColors) do
			part.Transparency=if state=="Defeated" then 0.42 else 0
			part.Color=if state=="Defeated" then color:Lerp(Color3.fromRGB(39,47,61),0.75)
				elseif state=="Warning" then color:Lerp(Color3.fromRGB(255,157,67),0.55)
				elseif state=="Tuned" then color:Lerp(Color3.fromRGB(255,216,131),0.35)
				elseif state=="Shielded" then color:Lerp(Color3.fromRGB(87,114,137),0.4) else color
		end
	end
	stateAppearance()
	local stateConnection=anchor:GetAttributeChangedSignal("VisualState"):Connect(stateAppearance)
	local motion
	if shapeName=="Tidewing" then
		local elapsed=0
		motion=RunService.Heartbeat:Connect(function(dt)
			elapsed+=dt
			if elapsed<1/18 then return end
			elapsed=0
			local t=workspace:GetServerTimeNow()*.42
			visual:PivotTo(anchor.CFrame*CFrame.new(0,1.5*math.sin(t),0)*CFrame.Angles(0,math.rad(5)*math.cos(t),math.rad(5)*math.sin(t)))
		end)
	end
	anchor.Destroying:Once(function() if motion then motion:Disconnect() end;stateConnection:Disconnect() end)
end
script.Destroying:Once(function()
	for _,entry in pairs(prototypes) do
		if entry.visual then entry.visual:Destroy() end
		if entry.mesh then entry.mesh:Destroy() end
	end
end)

local processed = setmetatable({}, {__mode="k"})
local function attach(anchor)
	if processed[anchor] then return end
	processed[anchor] = true
	task.spawn(build, anchor)
end
CollectionService:GetInstanceAddedSignal("AetherSculpture"):Connect(attach)
for _, anchor in ipairs(CollectionService:GetTagged("AetherSculpture")) do attach(anchor) end

-- BEGIN RESOURCE POLISH
-- Mining gather nodes (host part GatherNode=<AetherData resource>, §42) gain a
-- small crystal cluster tinted with the ore's colour. Bounded: at most POLISH_LIMIT nodes,
-- one shared prototype per ore (scaled per clone), skipped where a sculpture already exists
-- (including forged Shape parts such as OreVein meshes).
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local POLISH_LIMIT = 64
local polished = setmetatable({}, {__mode="k"})
local polishCount = 0
local resourceItems
local function worldHalfExtents(part)
	local cf, half = part.CFrame, part.Size/2
	local function axis(component)
		return math.abs(cf.RightVector[component])*half.X+math.abs(cf.UpVector[component])*half.Y+math.abs(cf.LookVector[component])*half.Z
	end
	return axis("X"), axis("Y"), axis("Z")
end
local function nearSculpture(node)
	if node:GetAttribute("Shape") then return true end
	local parent = node.Parent
	if not parent or parent == workspace then return false end
	local checked = 0
	for _, sibling in ipairs(parent:GetChildren()) do
		checked += 1
		if checked > 48 then break end
		if sibling ~= node and sibling:IsA("BasePart") and sibling:GetAttribute("Shape") and (sibling.Position-node.Position).Magnitude < 6 then return true end
	end
	return false
end
-- §42: `prompt` is the node host part (GatherNode); nodes carry no prompt now.
local function polish(prompt)
	if polished[prompt] or polishCount >= POLISH_LIMIT or not prompt.Parent then return end
	local def = resourceItems[prompt:GetAttribute("GatherNode")]
	if type(def) ~= "table" or def.kind ~= "resource" or def.skill ~= "Mining" then return end
	local node = prompt
	if not node or not node:IsA("BasePart") or nearSculpture(node) then return end
	local halfX, halfY, halfZ = worldHalfExtents(node)
	local footprint = 2*math.min(halfX, halfZ)
	if footprint < 1 or footprint > 30 then return end
	polished[prompt] = true
	polishCount += 1
	local ok, tint = pcall(Color3.fromHex, def.color)
	local template, temporary = prototype("OreCluster", 1, if ok then tint else nil)
	if not template then return end
	local visual = if temporary then template else template:Clone()
	if not node.Parent then visual:Destroy(); return end
	local factor = math.clamp(footprint*.3, .5, 3)
	if factor ~= 1 then
		if visual:IsA("Model") then pcall(visual.ScaleTo, visual, factor)
		elseif visual:IsA("BasePart") then
			visual.Size *= factor
			visual.PivotOffset = CFrame.new(visual.PivotOffset.Position*factor)
		end
	end
	visual.Name = "Ore polish"
	local yaw = math.rad((math.floor(node.Position.X*7+node.Position.Z*13)) % 360)
	visual:PivotTo(CFrame.new(node.Position+Vector3.new(0, halfY-.1*factor, 0))*CFrame.Angles(0, yaw, 0))
	visual.Parent = node
end
local function considerPrompt(instance)
	if not instance:IsA("BasePart") then return end
	if instance:GetAttribute("GatherNode") == nil then return end
	task.defer(polish, instance)
end
task.spawn(function()
	local module = ReplicatedStorage:WaitForChild("AetherData", 20)
	if not module or not module:IsA("ModuleScript") then return end
	local ok, data = pcall(require, module)
	if not ok or type(data) ~= "table" or type(data.Items) ~= "table" then return end
	resourceItems = data.Items
	workspace.DescendantAdded:Connect(considerPrompt)
	for _, instance in ipairs(workspace:GetDescendants()) do considerPrompt(instance) end
end)
-- END RESOURCE POLISH

-- Each client renders companions from server-owned bond attributes.
local Players = game:GetService("Players")
local companions = {}
local function updateCompanion(player)
	local character = player.Character
	local root = character and character:FindFirstChild("HumanoidRootPart")
	local bonded = (player:GetAttribute("CompanionBond") or 0) > 0
	local anchor = companions[player]
	if not bonded or not root then
		if anchor then anchor:Destroy(); companions[player] = nil end
		return
	end
	if not anchor then
		anchor = Instance.new("Part")
		anchor.Name = "Tidewing companion"
		anchor.Anchored = true
		anchor.CanCollide = false
		anchor.CanTouch = false
		anchor.CanQuery = false
		anchor.Transparency = 1
		-- §48: drawn by creatures.client.lua as a small forged ray (IsleCreature).
		anchor:SetAttribute("CreatureRig", "ray")
		anchor:SetAttribute("CreatureScale", 0.22)
		anchor:SetAttribute("Color", "3F7CAC")
		anchor:SetAttribute("CreatureTier", "pet")
		anchor.CFrame = root.CFrame * CFrame.new(3, 2, 2)
		anchor.Parent = workspace
		companions[player] = anchor
		CollectionService:AddTag(anchor, "IsleCreature")
	end
	anchor.CFrame = root.CFrame * CFrame.new(3, 2, 2)
end
local companionElapsed = 0
RunService.Heartbeat:Connect(function(dt)
	companionElapsed += dt
	if companionElapsed < 1/18 then return end
	companionElapsed = 0
	for _, player in Players:GetPlayers() do updateCompanion(player) end
end)
Players.PlayerRemoving:Connect(function(player)
	if companions[player] then companions[player]:Destroy(); companions[player] = nil end
end)
